/**
 * Helper to fetch a 5-word set for any Hive and setNumber.
 * Supports words supplied as simple strings (e.g. 'water'), arrays (e.g. ['water']),
 * or legacy metadata arrays (e.g. ['water', 'noun', '...']).
 */
window.getHiveWordSet = function(hiveId, setNumber) {
  const hiveBank = window.HIVE_WORDS_DATA[hiveId] || window.HIVE_WORDS_DATA['Beginner'];
  const safeSetIdx = Math.max(0, Math.min(hiveBank.length - 1, (setNumber || 1) - 1));
  const rawSet = hiveBank[safeSetIdx] || hiveBank[0];

  return rawSet.map(item => {
    let wordStr = '';
    let pos = 'noun';
    let sentence = '';
    let definition = '';

    if (typeof item === 'string') {
      wordStr = item;
    } else if (Array.isArray(item)) {
      wordStr = item[0] || '';
      pos = item[1] || 'noun';
      sentence = item[2] || `Spell the word '${wordStr}'.`;
      definition = item[3] || `A vocabulary word to practice.`;
    } else if (item && typeof item === 'object') {
      wordStr = item.word || '';
      pos = item.pos || 'noun';
      sentence = item.sentence || '';
      definition = item.definition || item.hint || '';
    }

    return {
      word: (wordStr || '').trim(),
      pos,
      sentence,
      definition: definition || `Definition for ${wordStr}`
    };
  });
};

/**
 * Helper to fetch 10 random representative words across all 30 sets of a Hive
 * for the Milestone Challenge Gate (Test Out).
 * Truly samples and randomizes 10 unique words from the requested Hive.
 */
window.getChallengeWordSet = function(hiveId) {
  const hiveBank = window.HIVE_WORDS_DATA[hiveId] || window.HIVE_WORDS_DATA['Beginner'];
  const allWords = [];

  // Flatten and collect all unique words from this hive
  hiveBank.forEach(setWords => {
    if (Array.isArray(setWords)) {
      setWords.forEach(item => {
        let wordObj = null;
        if (typeof item === 'string') {
          wordObj = { word: item, pos: 'noun', sentence: `Spell the word '${item}'.`, definition: 'Vocabulary word.' };
        } else if (Array.isArray(item)) {
          wordObj = { word: item[0] || '', pos: item[1] || 'noun', sentence: item[2] || '', definition: item[3] || '' };
        } else if (item && typeof item === 'object') {
          wordObj = { word: item.word || '', pos: item.pos || 'noun', sentence: item.sentence || '', definition: item.definition || item.hint || '' };
        }

        if (wordObj && wordObj.word && !allWords.some(w => w.word.toLowerCase() === wordObj.word.toLowerCase())) {
          allWords.push(wordObj);
        }
      });
    }
  });

  // Fisher-Yates shuffle to pick 10 random words
  const shuffled = [...allWords];
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = shuffled[i];
    shuffled[i] = shuffled[j];
    shuffled[j] = temp;
  }

  return (shuffled.length >= 10 ? shuffled.slice(0, 10) : shuffled);
};

/**
 * Utility to allow dynamic addition of custom word sets
 * simply by passing an array of strings: addCustomHiveWordSet('Beginner', ['cat', 'dog', 'bird'])
 */
window.addCustomHiveWordSet = function(hiveId, wordsArray) {
  if (!window.HIVE_WORDS_DATA[hiveId]) {
    window.HIVE_WORDS_DATA[hiveId] = [];
  }
  const cleanWords = wordsArray.map(w => typeof w === 'string' ? w.trim() : (w[0] || '').trim());
  window.HIVE_WORDS_DATA[hiveId].push(cleanWords);
  return window.HIVE_WORDS_DATA[hiveId].length;
};

